Current task: update esbuild config in runner (full overwrite, bash only).
Copy/paste:
Bashcat > runtime/node/esbuild-runner.cjs <<'EOF'
const esbuild = require("esbuild");
const fs = require("fs");
const path = require("path");

(async () => {
  try {
    const projectId = process.argv[2];

    const projectRoot = path.join(
      process.cwd(),
      "runtime/workspaces/default/projects",
      projectId
    );

    const entry = path.join(projectRoot, "app/page.tsx");

    if (!fs.existsSync(entry)) {
      throw new Error("Entry not found: " + entry);
    }

    const tempEntry = path.join(projectRoot, "__preview-entry.tsx");

    fs.writeFileSync(
      tempEntry,
      `
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app/page";

const root = document.getElementById("root");

if (!root) throw new Error("Missing #root");

ReactDOM.createRoot(root).render(
  React.createElement(App)
);
`
    );

    const result = await esbuild.build({
      entryPoints: [tempEntry],
      bundle: true,
      write: false,
      platform: "browser",
      format: "iife",
      jsx: "automatic",
      loader: {
        ".ts": "ts",
        ".tsx": "tsx",
        ".css": "empty",
      },
      external: [
        "react",
        "react-dom",
        "next/*",
      ],
    });

    fs.unlinkSync(tempEntry);

    process.stdout.write(result.outputFiles[0].text);

  } catch (err) {
    console.error("BUILD_ERROR_START");
    console.error(err);
    console.error("BUILD_ERROR_END");
    process.exit(1);
  }
})();
EOF

